package com.tradingapp.data.model
data class Holding(val symbol: String, val exchange: String, val quantity: Int, val avgCost: Double, val currentPrice: Double, val currentValue: Double, val pnl: Double, val pnlPercent: Double, val instrumentToken: Long = 0, val product: String = "DELIVERY", val priceAvailable: Boolean = false, val priceUpdatedAt: Long = 0, val priceStale: Boolean = true) { val isProfit get() = pnl >= 0 }
